<script>
    import { onMount } from 'svelte';
    import gsap from 'gsap';
    
    let container;
    let logo;
    let showAnimation = true;
  
    onMount(() => {
      // Check if user has already visited this session
      const hasVisited = sessionStorage.getItem('hasVisited') === 'true';
      
      if (hasVisited) {
        // Skip animation, just hide immediately
        showAnimation = false;
        return;
      }
  
      // Mark as visited
      sessionStorage.setItem('hasVisited', 'true');
  
      // Disable scrolling during animation
      document.body.style.overflow = 'hidden';
  
      const tl = gsap.timeline({
        onComplete: () => {
          document.body.style.overflow = 'auto';
          showAnimation = false;
        }
      });
  
      // Sequence: white → gradient fades in → logo fades in → fade out
      tl.to('.gradation', {
        opacity: 1,
        duration: 1.2,
        ease: 'power2.inOut'
      })
      .to(logo, {
        opacity: 1,
        duration: 0.8,
        ease: 'power2.out',
        delay: 0.4
      })
      .to(container, {
        opacity: 0,
        duration: 0.6,
        ease: 'power2.inOut',
        delay: 1
      });
    });
  </script>
  
  {#if showAnimation}
    <div class="opening-container" bind:this={container}>
      <div class="gradation">
        <div></div>
        <div></div>
        <div></div>
        <div></div>
      </div>
  
      <div class="logo" bind:this={logo}>
