  <style>
    .opening-container {
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100vh;
      background: #ffffff;
      z-index: 99999;
      display: flex;
      align-items: center;
      justify-content: center;
    }
  
    .gradation {
      width: 100vw;
      height: 100vh;
      position: absolute;
      left: 0;
      right: 0;
      top: 0;
      bottom: 0;
      overflow: hidden;
      opacity: 0;
    }
  
    .gradation div {
      position: absolute;
      border-radius: 50%;
      animation: gradient 4s infinite;
      filter: blur(100px);
    }
  
    @keyframes gradient {
      70% {
        transform: scale(1.5) translate(80px);
      }
    }
  
    .gradation div:nth-child(1) {
      height: 90%;
      width: 80%;
      background-color: #ced1c8;
      left: -30%;
      top: -10%;
    }
  
    .gradation div:nth-child(2) {
      height: 80%;
      width: 60%;
      background-color: #8ac5db;
      top: -10%;
      right: 0%;
      animation-delay: .8s;
    }
  
    .gradation div:nth-child(3) {
      height: 65%;
      width: 80%;
      background-color: #005fac;
      bottom: -15%;
      right: -20%;
      animation-delay: 0.3s;
    }
  
    .gradation div:nth-child(4) {
      height: 50%;
      width: 75%;
      background-color: #f1af9b;
      bottom: -10%;
      left: -50%;
      animation-delay: 1.2s;
    }
  
    .gradation::after {
      position: absolute;
      content: "";
      height: 100%;
      width: 100%;
      z-index: 1;
    }
  
    .logo {
      opacity: 0;
      position: relative;
      z-index: 10;
      width: 50vw;
      height: auto;
    }
  
    .logo svg {
      filter: drop-shadow(0 10px 30px rgba(0, 0, 0, 0.2));
      width: 100%;
      height: auto;
    }
  
    @media (max-width: 768px) {
      .logo {
        width: 75vw;
      }
    }
  </style>